package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.access.AccessService;
import net.officefloor.hq.app.access.Role;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.pool.PoolMember;
import net.officefloor.hq.app.pool.PoolMemberRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.statement.StatementRepository;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * Merging a person into another on the same sheet. Only a steward may; merging a person into themselves, or
 * when either of them is retired, is refused. The merged person's claims move to the other (numbers and dates
 * kept, listed after the other's claims in the order they were added, each released from any figure a
 * statement bound); their name and aliases become the other's aliases; their patrons are added to the
 * other's (never the other themselves, no repeats); anyone naming them as patron names the other instead
 * (no repeats); their pool memberships move to the other, the shares added up (at most 100.00) where the
 * other is already a member. Their statements, holds, watchers and contact are dropped with them.
 */
@Service
public class PersonMergeService {

    private static final BigDecimal FULL_SHARE = new BigDecimal("100.00");

    private final PersonRepository people;
    private final PatronRepository patrons;
    private final WatchRepository watches;
    private final ClaimRepository claims;
    private final StatementRepository statements;
    private final PoolMemberRepository poolMembers;
    private final AccessService access;
    private final SheetRepository sheetRows;
    private final Rollup rollup;
    private final ApplicationEventPublisher events;

    public PersonMergeService(PersonRepository people, PatronRepository patrons, WatchRepository watches,
            ClaimRepository claims, StatementRepository statements, PoolMemberRepository poolMembers,
            AccessService access, SheetRepository sheetRows, Rollup rollup, ApplicationEventPublisher events) {
        this.people = people;
        this.patrons = patrons;
        this.watches = watches;
        this.claims = claims;
        this.statements = statements;
        this.poolMembers = poolMembers;
        this.access = access;
        this.sheetRows = sheetRows;
        this.rollup = rollup;
        this.events = events;
    }

    /** Merge the person into the other; answers with the other as they are now. */
    @Transactional
    public Person merge(String sheetId, String user, long personId, long intoId) {
        sheetRows.lockById(sheetId);
        if (access.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can merge people");
        }
        if (personId == intoId) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be merged into themselves");
        }
        Person from = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        Person into = people.findByIdAndSheetId(intoId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "No such person"));
        if (from.isRetired() || into.isRetired()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A retired person cannot be merged");
        }
        Rollup.Figures before = rollup.figures(sheetId);

        List<Claim> moving = new ArrayList<>(claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId));
        moving.sort(Comparator.comparing(Claim::getId));
        for (Claim claim : moving) {
            claim.setPersonId(intoId);
            claim.unbind();
        }
        claims.flush();
        for (Claim claim : moving) {
            claims.relist(claim.getId());
        }

        into.addAlias(from.getName());
        from.getAliases().forEach(into::addAlias);

        mergePatrons(sheetId, personId, intoId);
        mergePools(personId, intoId);
        watches.deleteAll(watches.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId));
        statements.deleteAll(statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId));
        watches.flush();
        people.delete(from);
        people.flush();

        events.publishEvent(new PersonMerged(sheetId, user, from.getName(), into.getName()));
        rollup.changed(sheetId, user, before);
        return into;
    }

    /** The merged person's patrons join the other's, and whoever named the merged person names the other. */
    private void mergePatrons(String sheetId, long personId, long intoId) {
        List<Patron> theirs = patrons.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
        List<Patron> naming = patrons.findBySheetIdAndPatronIdOrderByIdAsc(sheetId, personId);
        Set<Long> intoPatrons = patrons.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, intoId).stream()
                .map(Patron::getPatronId).collect(Collectors.toCollection(LinkedHashSet::new));
        patrons.deleteAll(theirs);
        patrons.deleteAll(naming);
        patrons.flush();
        List<Patron> added = new ArrayList<>();
        for (Patron p : theirs) {
            long patronId = p.getPatronId();
            if (patronId != intoId && intoPatrons.add(patronId)) {
                added.add(new Patron(sheetId, intoId, patronId));
            }
        }
        for (Patron p : naming) {
            long namer = p.getPersonId();
            if (namer != intoId && !patrons.existsByPersonIdAndPatronId(namer, intoId)
                    && added.stream().noneMatch(a -> a.getPersonId() == namer)) {
                added.add(new Patron(sheetId, namer, intoId));
            }
        }
        patrons.saveAllAndFlush(added);
    }

    /** The merged person's pool memberships move to the other, adding shares where the other is a member. */
    private void mergePools(long personId, long intoId) {
        Map<Long, PoolMember> intoByPool = poolMembers.findByPersonId(intoId).stream()
                .collect(Collectors.toMap(PoolMember::getPoolId, Function.identity()));
        for (PoolMember member : poolMembers.findByPersonId(personId)) {
            PoolMember existing = intoByPool.get(member.getPoolId());
            if (existing == null) {
                member.setPersonId(intoId);
            } else {
                existing.setShare(existing.getShare().add(member.getShare()).min(FULL_SHARE));
                poolMembers.delete(member);
            }
        }
        poolMembers.flush();
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import net.officefloor.hq.app.claim.Holds;

/**
 * A person on a sheet, with a name, their own terms (null: none) and their grades (A, B or C), each from a date (see {@link #gradeOn}), the date they are retired from (null while
 * not retired), their holds (see {@link #heldOn}) and the version it was last saved at.
 */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    private List<GradeFrom> grades = new ArrayList<>();

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_alias", joinColumns = @JoinColumn(name = "person_id"))
    @Column(name = "alias")
    private List<String> aliases = new ArrayList<>();

    @Column(name = "terms")
    private Integer terms;

    @Column(name = "contact")
    private String contact;

    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    @OrderBy("fromDate ASC")
    private List<HoldSpan> holds = new ArrayList<>();

    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade) {
        this.sheetId = sheetId;
        this.name = name;
        this.grades.add(new GradeFrom(grade, null));
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public long getVersion() {
        return version;
    }

    /**
     * The grade in force on the date: the one whose from-date is the latest on or before it, the first
     * grade (no from-date) applying from the beginning of time.
     */
    public String gradeOn(LocalDate date) {
        return grades.stream()
                .filter(g -> g.getFromDate() == null || !g.getFromDate().isAfter(date))
                .max(Comparator.comparing(GradeFrom::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .map(GradeFrom::getGrade).orElse(null);
    }

    /** The grades the person was given, each from its date. */
    public List<GradeFrom> getGrades() {
        return List.copyOf(grades);
    }

    /** Record the grade from the date, keeping the others; one already recorded from that date is replaced. */
    public void gradeFrom(String grade, LocalDate from) {
        grades.removeIf(g -> g.getFromDate() != null && Objects.equals(g.getFromDate(), from));
        grades.add(new GradeFrom(grade, from));
    }

    /** The person's aliases, sorted as names are compared (without regard to case). */
    public List<String> getAliases() {
        return aliases.stream().sorted(String.CASE_INSENSITIVE_ORDER).toList();
    }

    /** Add an alias, stored trimmed, keeping the others. */
    public void addAlias(String alias) {
        aliases.add(alias);
    }

    /** The person's own terms in days, in force on every date; null when they have none. */
    public Integer getTerms() {
        return terms;
    }

    public void setTerms(Integer terms) {
        this.terms = terms;
    }

    /** The person's contact, trimmed and lower-cased; null when they have none. */
    public String getContact() {
        return contact;
    }

    public void setContact(String contact) {
        this.contact = contact;
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    /** Whether the person has any hold, whatever its dates. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** The person's holds, earliest from-date first. */
    public List<HoldSpan> getHolds() {
        return holds.stream().sorted(Comparator.comparing(HoldSpan::getFromDate)).toList();
    }

    /** Whether a hold covers the date: their OPEN claims dated then count in no live total. */
    public boolean heldOn(LocalDate date) {
        return holds.stream().anyMatch(h -> h.covers(date));
    }

    /** Add a hold from a date to an optional date, keeping the others. */
    public void hold(LocalDate from, LocalDate to) {
        holds.add(new HoldSpan(from, to));
    }

    /** Whether the retirement date is reached on the sheet's today: on or after it. */
    public boolean retiredOn(LocalDate today) {
        return retiredFrom != null && !today.isBefore(retiredFrom);
    }

    /** The person's holds and retirement, as they leave claims out of the live totals. */
    public Holds leaves() {
        return new Holds() {
            @Override
            public boolean on(LocalDate date) {
                return heldOn(date);
            }

            @Override
            public boolean retiredOn(LocalDate today) {
                return Person.this.retiredOn(today);
            }
        };
    }

    /** Whether a retirement date is set: retired at once, whatever the date. */
    public boolean isRetired() {
        return retiredFrom != null;
    }
