    @TransactionalEventListener
    public void on(TemplateSaved e) {
        change(e.sheetId(), e.user(), "TEMPLATE_SAVED sheet=" + e.sheetId() + " by=" + e.user() + " name=" + e.name()
                + " amount=" + e.amount().setScale(2, RoundingMode.HALF_UP).toPlainString() + " note=" + e.note());
    }

    @TransactionalEventListener
    public void on(PoolAdded e) {
        change(e.sheetId(), e.user(), "POOL_ADDED sheet=" + e.sheetId() + " by=" + e.user() + " name=" + e.name());
    }

    @TransactionalEventListener
    public void on(PoolMemberAdded e) {
        change(e.sheetId(), e.user(), "POOL_MEMBER_ADDED sheet=" + e.sheetId() + " by=" + e.user() + " pool=" + e.pool()
                + " name=" + e.name() + " share=" + e.share().setScale(2, RoundingMode.HALF_UP).toPlainString());
    }

    @TransactionalEventListener
    public void on(HolidayAdded e) {
        change(e.sheetId(), e.user(), "HOLIDAY_ADDED sheet=" + e.sheetId() + " by=" + e.user() + " date=" + e.date());
    }

    @TransactionalEventListener
    public void on(PeriodClosed e) {
        change(e.sheetId(), e.user(), (e.soft() ? "PERIOD_SOFT_CLOSED" : "PERIOD_CLOSED") + " sheet=" + e.sheetId() + " by=" + e.user()
                + " period=" + e.name() + " total=" + e.total().setScale(2, RoundingMode.HALF_UP).toPlainString()
                + (e.auto() ? " auto=yes" : ""));
    }

    @TransactionalEventListener
    public void on(PeriodReopened e) {
        change(e.sheetId(), e.user(), "PERIOD_REOPENED sheet=" + e.sheetId() + " by=" + e.user() + " period=" + e.name());
    }

    @TransactionalEventListener
    public void on(StatementTaken e) {
        change(e.sheetId(), e.user(), "STATEMENT sheet=" + e.sheetId() + " by=" + e.user() + " name=" + e.name()
                + " due-total=" + (e.dueTotal() == null ? "n/a"
                        : e.dueTotal().setScale(2, RoundingMode.HALF_UP).toPlainString())
                + " claims=" + e.claims() + (e.asOf() == null ? "" : " asof=" + e.asOf()));
    }

    @TransactionalEventListener
    public void on(StatementCancelled e) {
        change(e.sheetId(), e.user(), "STATEMENT_CANCELLED sheet=" + e.sheetId() + " by=" + e.user() + " name=" + e.name()
                + " due-total=" + (e.dueTotal() == null ? "n/a"
                        : e.dueTotal().setScale(2, RoundingMode.HALF_UP).toPlainString()));
    }

    @TransactionalEventListener
    public void on(BatchSettled e) {
        change(e.sheetId(), e.user(), "BATCH_SETTLED sheet=" + e.sheetId() + " by=" + e.user() + " batch=" + e.batch()
                + " count=" + e.count() + " total=" + e.total().setScale(2, RoundingMode.HALF_UP).toPlainString());
    }

    @TransactionalEventListener
    public void on(Delegated e) {
        change(e.sheetId(), e.user(), "DELEGATED sheet=" + e.sheetId() + " by=" + e.user() + " user=" + e.name()
                + " from=" + e.from() + " to=" + e.to());
    }

    @TransactionalEventListener
    public void on(DaySnapshot e) {
        // the day being left decides whether the user acted in a delegated role, not the today it moves to
        String delegator = access.delegator(e.sheetId(), e.user(), e.day());
        for (Rollup.PersonFigures p : e.people()) {
            String line = "SNAPSHOT sheet=" + e.sheetId() + " by=" + e.user() + " name=" + p.name()
                    + " due-total=" + p.dueTotal();
            audit.record(delegator == null ? line : line + " for=" + delegator);
        }
    }

    @TransactionalEventListener
    public void on(RollupChanged e) {
        for (Rollup.PersonFigures p : e.people()) {
            audit.record("ROLLUP sheet=" + e.sheetId() + " by=" + e.user() + " person=" + p.name()
                    + " claimed=" + p.claimed() + " due-total=" + p.dueTotal() + " overdue-total=" + p.overdueTotal());
        }
        if (e.totals() != null) {
            audit.record("TOTALS sheet=" + e.sheetId() + " by=" + e.user()
                    + " claimed-total=" + e.totals().claimed() + " due-total=" + e.totals().dueTotal()
                    + " overdue-total=" + e.totals().overdueTotal());
        }
    }
}
