76	    /** Transfer the person to the other sheet (started empty when its id was never used). */
77	    @Transactional
78	    public void transfer(String sheetId, String user, long personId, String toSheet) {
79	        if (toSheet.equals(sheetId)) {
80	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be transferred to their own sheet");
81	        }
82	        sheets.load(toSheet, user);
83	        // both sheets locked in the same order, so transfers each way between them take turns
84	        Stream.of(sheetId, toSheet).sorted().forEach(sheetRows::lockById);
85	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
86	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can transfer people");
87	        }
88	        if (sheets.isArchived(toSheet)) {
89	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The other sheet is archived");
90	        }
91	        Person person = people.findByIdAndSheetId(personId, sheetId)
92	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
93	        if (person.isRetired()) {
94	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A retired person cannot be transferred");
95	        }
96	        List<String> names = new ArrayList<>(person.getAliases());
97	        names.add(person.getName());
98	        for (String name : names) {
99	            if (people.existsBySheetIdAndNameIgnoreCase(toSheet, name) || people.existsAlias(toSheet, name, null)) {
100	                throw new ResponseStatusException(HttpStatus.CONFLICT, "Name already in use on the other sheet");
101	            }
102	        }
103	        if (person.getContact() != null && people.existsBySheetIdAndContact(toSheet, person.getContact())) {
104	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Contact already in use on the other sheet");
105	        }
106	        Rollup.Figures beforeHere = rollup.figures(sheetId);
107	        Rollup.Figures beforeThere = rollup.figures(toSheet);
108	
109	        Person arrived = people.saveAndFlush(person.arriving(toSheet));
110	        // added oldest listed first, so they list on the other sheet in the order they listed here
111	        List<Claim> leaving = new ArrayList<>(claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId));
112	        Collections.reverse(leaving);
113	        List<Claim> arriving = new ArrayList<>();
114	        Map<Claim, String> oldNumbers = new HashMap<>();
115	        Map<Claim, LocalDate> openedOn = new HashMap<>();
116	        Map<Claim, Long> addedAs = new HashMap<>();
117	        for (Claim claim : leaving) {
118	            Claim copy = claim.arriving(toSheet, arrived.getId());
119	            arriving.add(copy);
120	            if (claim.getShownNumber() != null) {
121	                oldNumbers.put(copy, claim.getShownNumber());
122	            }
123	            openedOn.put(copy, openedOn(claim));
124	            addedAs.put(copy, claim.getId());
125	            tags.use(toSheet, claim.getTags());
126	        }
127	        claims.saveAllAndFlush(arriving);
128	
129	        Map<String, String> renumbered = new HashMap<>();
130	        arriving.stream().filter(oldNumbers::containsKey)
131	                .sorted(Comparator.comparing(openedOn::get).thenComparing(addedAs::get))
132	                .forEach(claim -> {
133	                    claimService.numberArrived(toSheet, claim);
134	                    renumbered.put(oldNumbers.get(claim), claim.getShownNumber());
135	                });
136	        // a correction, or a claim split off another, names the claim it came from by its new number
137	        for (Claim claim : arriving) {
138	            if (claim.getCorrects() != null) {
139	                claim.setCorrects(renumbered.getOrDefault(claim.getCorrects(), claim.getCorrects()));
140	            }
141	            if (claim.getSplitFrom() != null) {
142	                claim.setSplitFrom(renumbered.getOrDefault(claim.getSplitFrom(), claim.getSplitFrom()));
143	            }
144	        }
145	        claims.flush();
146	
147	        patrons.deleteAll(patrons.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId));
148	        patrons.deleteAll(patrons.findBySheetIdAndPatronIdOrderByIdAsc(sheetId, personId));
149	        poolMembers.deleteAll(poolMembers.findByPersonId(personId));
150	        watches.deleteAll(watches.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId));
151	        statements.deleteAll(statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId));
152	        claims.deleteAll(leaving);
153	        claims.flush();
154	        people.delete(person);
155	        people.flush();
156	
157	        events.publishEvent(new PersonTransferred(sheetId, user, person.getName(), toSheet, null));
158	        rollup.changed(sheetId, user, beforeHere);
159	        events.publishEvent(new PersonTransferred(toSheet, user, person.getName(), null, sheetId));
160	        rollup.changed(toSheet, user, beforeThere);
